package com.skycraft.loot;

import com.skycraft.Skycraft;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.Rarity;
import net.minecraftforge.eventbus.api.IEventBus;
import net.minecraftforge.registries.DeferredRegister;
import net.minecraftforge.registries.ForgeRegistries;
import net.minecraftforge.registries.RegistryObject;

/**
 * Skycraft's loot economy (see {@code docs/LOOT.md}): the container taxonomy ({@code skycraft:containers/<kind>/<tier>},
 * generated by {@code tools/loot_data.py}), the loot level ({@link LootLevels}), material ladders ({@link LootTiers}),
 * loot functions ({@link LootFunctions}), collections ({@link Collectibles}, {@link LegendaryUniques},
 * {@link CollectionTracker}), restocking ({@link Restock}) and the {@code /skyloot} dev command ({@link LootCommand}).
 */
public final class LootModule {
    public static final DeferredRegister<Item> ITEMS = DeferredRegister.create(ForgeRegistries.ITEMS, Skycraft.MODID);

    /** A Stone of Barenziah, before Vex names it: an "Unusual Gem" (24, one per named dungeon). */
    public static final RegistryObject<Item> UNUSUAL_GEM = ITEMS.register("unusual_gem",
            () -> new CollectibleItem(CollectibleItem.Kind.GEM, new Item.Properties().stacksTo(1).rarity(Rarity.UNCOMMON)));
    public static final RegistryObject<Item> CROWN_OF_BARENZIAH = ITEMS.register("crown_of_barenziah",
            () -> new CollectibleItem(CollectibleItem.Kind.CROWN, new Item.Properties().stacksTo(1).rarity(Rarity.EPIC)));
    public static final RegistryObject<Item> BLACK_BOOK = ITEMS.register("black_book",
            () -> new BlackBookItem(new Item.Properties().stacksTo(1).rarity(Rarity.EPIC)));
    public static final RegistryObject<Item> ELDER_SCROLL = ITEMS.register("elder_scroll",
            () -> new CollectibleItem(CollectibleItem.Kind.SCROLL, new Item.Properties().stacksTo(1).rarity(Rarity.EPIC)));
    public static final RegistryObject<Item> REGIONAL_TREASURE = ITEMS.register("regional_treasure",
            () -> new CollectibleItem(CollectibleItem.Kind.TREASURE, new Item.Properties().stacksTo(1).rarity(Rarity.RARE)));

    private LootModule() {}

    public static void init(IEventBus modBus) {
        ITEMS.register(modBus);
        AddTableModifier.init(modBus);
        LootFunctions.init(modBus);
    }
}
